<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/page_auth.php';
require_once __DIR__ . '/../config/auth.php';
$pdo = getDatabaseConnection();
imcRequirePageAccess('whatsapp.consent.read', null, $pdo);
$csrf = htmlspecialchars(generateCsrfToken(), ENT_QUOTES, 'UTF-8');
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?= $csrf ?>"><title>Consentements WhatsApp — Clarodaro</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f6f8;color:#17212b;font:16px Arial,sans-serif}header{background:#075e54;color:#fff;padding:20px max(16px,calc((100% - 980px)/2))}main{max-width:980px;margin:22px auto;padding:0 14px}.card{background:#fff;border:1px solid #dce4e8;border-radius:12px;padding:20px;margin-bottom:16px}h1{margin:0 0 6px;font-size:24px}h2{color:#075e54;margin:0 0 14px;font-size:20px}input,button{font:inherit;padding:11px;border-radius:7px}input{border:1px solid #b8c5cc;width:100%}button{border:0;background:#087f5b;color:white;font-weight:700;cursor:pointer}button:disabled{opacity:.55}.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.row input{flex:1;min-width:220px}.hint{font-size:13px;color:#52616b;line-height:1.5}.result{padding:12px;background:#edf7f1;border-radius:8px;margin-top:12px;white-space:pre-wrap}.error{background:#fff0f0;color:#8a1717}.parent{display:block;width:100%;text-align:left;margin:6px 0;background:#f0f7f4;color:#173b32;border:1px solid #c9ded5}.purpose{display:flex;gap:8px;align-items:center;margin:10px 0}.purpose input{width:auto}.meta{font-size:13px;color:#52616b}@media(max-width:600px){.card{padding:15px}}
</style></head><body><header><h1>Gestion des consentements WhatsApp</h1><p>Clarodaro · Consentement parent par finalité</p></header><main>
<section class="card"><h2>1. Rechercher un parent</h2><div class="row"><input id="q" type="search" placeholder="Nom, téléphone ou e-mail du parent"><button id="search">Rechercher</button></div><div id="matches"></div><p class="hint">Les résultats affichent les coordonnées déjà enregistrées dans le dossier du parent. L’adresse e-mail ne peut pas être remplacée depuis cet écran.</p></section>
<section class="card" id="details" hidden><h2 id="parentTitle">Consentements du parent</h2><p id="parentMeta" class="meta"></p><div id="consents"></div>
<h2 style="margin-top:22px">Consentement papier</h2><p class="hint">Après avoir reçu le formulaire signé, cochez uniquement les finalités autorisées et saisissez une référence d’archive (nom du document, numéro de dossier ou emplacement sécurisé). N’enregistrez jamais un accord papier sans preuve.</p>
<div id="paperPurposes">
<label class="purpose"><input type="checkbox" value="ATTENDANCE"> Présences et absences</label>
<label class="purpose"><input type="checkbox" value="RESULTS_AVAILABLE"> Disponibilité des résultats</label>
<label class="purpose"><input type="checkbox" value="PAYMENT_REMINDER"> Rappels de paiement</label>
<label class="purpose"><input type="checkbox" value="GENERAL"> Communications générales</label>
</div>
<input id="paperPhone" placeholder="Téléphone autorisé au format +509..." style="margin:8px 0">
<input id="paperEvidence" placeholder="Référence de la preuve papier (obligatoire)">
<div class="row" style="margin-top:10px"><button id="savePaper">Enregistrer le consentement papier</button><button id="invite" type="button">Envoyer une invitation par e-mail</button></div>
<div id="feedback" class="result" hidden role="status"></div></section>
</main>
<script>
const csrf=document.querySelector('meta[name="csrf-token"]').content,$=id=>document.getElementById(id);
let selected=null;
function message(text,error=false){$('feedback').hidden=false;$('feedback').textContent=text;$('feedback').classList.toggle('error',error)}
async function api(url,options={}){const r=await fetch(url,{credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json',...(options.body?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{})},...options});const d=await r.json().catch(()=>({success:false,error:'Réponse serveur invalide'}));if(!r.ok||d.success!==true)throw Error(d.error||('Erreur HTTP '+r.status));return d}
$('search').onclick=async()=>{const q=$('q').value.trim();if(q.length<2)return;try{const d=await api('/api/whatsapp/consent-parents-search.php?q='+encodeURIComponent(q));$('matches').replaceChildren();d.parents.forEach(p=>{const b=document.createElement('button');b.className='parent';b.textContent=[p.first_name,p.last_name].filter(Boolean).join(' ')+' · '+(p.email||'sans e-mail')+' · '+(p.phone||'sans téléphone');b.onclick=()=>selectParent(p);$('matches').appendChild(b)});if(!d.parents.length)$('matches').textContent='Aucun parent trouvé.'}catch(e){$('matches').textContent=e.message}};
async function selectParent(p){selected=p;$('details').hidden=false;$('parentTitle').textContent='Consentements — '+p.first_name+' '+p.last_name;$('parentMeta').textContent='E-mail : '+(p.email||'non renseigné')+' · Téléphone dossier : '+(p.phone||'non renseigné');$('paperPhone').value=p.phone||'';$('feedback').hidden=true;document.querySelectorAll('#paperPurposes input').forEach(x=>x.checked=false);await loadConsents()}
async function loadConsents(){try{const d=await api('/api/whatsapp/consents.php?parent_id='+encodeURIComponent(selected.id));$('consents').replaceChildren();if(!d.consents.length){$('consents').textContent='Aucun consentement enregistré.';return}d.consents.forEach(c=>{const box=document.createElement('div');box.className='result';const names={ATTENDANCE:'Présences et absences',RESULTS_AVAILABLE:'Résultats disponibles',PAYMENT_REMINDER:'Rappels de paiement',GENERAL:'Communications générales'};box.textContent=names[c.purpose]+' — '+c.status+' · '+(c.consent_method||c.consent_source||'méthode historique')+(c.evidence_reference?' · preuve : '+c.evidence_reference:'');if(c.status==='OPTED_IN'){const b=document.createElement('button');b.textContent='Retirer le consentement';b.style.marginTop='8px';b.onclick=()=>revoke(c);box.appendChild(document.createElement('br'));box.appendChild(b)}$('consents').appendChild(box)})}catch(e){message(e.message,true)}}
async function revoke(c){if(!confirm('Retirer le consentement pour cette finalité ? Les prochains envois seront bloqués.'))return;try{await api('/api/whatsapp/consents.php',{method:'POST',body:JSON.stringify({parent_id:selected.id,purpose:c.purpose,phone_e164:c.phone_e164,status:'OPTED_OUT',consent_source:'Retrait enregistré par l’établissement',consent_method:c.consent_method||'PAPER',evidence_reference:'Retrait enregistré dans Clarodaro'})});message('Consentement retiré. Les prochains messages pour cette finalité sont bloqués.');await loadConsents()}catch(e){message(e.message,true)}}
$('savePaper').onclick=async()=>{if(!selected)return;const purposes=[...document.querySelectorAll('#paperPurposes input:checked')].map(x=>x.value),phone=$('paperPhone').value.trim(),evidence=$('paperEvidence').value.trim();if(!purposes.length)return message('Choisissez au moins une finalité.',true);if(!/^\+[1-9][0-9]{7,14}$/.test(phone))return message('Numéro international E.164 requis.',true);if(evidence.length<3)return message('La référence de la preuve papier est obligatoire.',true);try{for(const purpose of purposes)await api('/api/whatsapp/consents.php',{method:'POST',body:JSON.stringify({parent_id:selected.id,purpose,phone_e164:phone,status:'OPTED_IN',consent_source:'PAPER',consent_method:'PAPER',evidence_reference:evidence})});message('Consentement papier enregistré pour '+purposes.length+' finalité(s).');$('paperEvidence').value='';await loadConsents()}catch(e){message(e.message,true)}};
$('invite').onclick=async()=>{if(!selected)return;if(!selected.email)return message('Ce parent ne possède pas d’adresse e-mail enregistrée. Mettez d’abord son dossier à jour.',true);try{const d=await api('/api/whatsapp/consent-invitations.php',{method:'POST',body:JSON.stringify({parent_id:selected.id})});message(d.message)}catch(e){message(e.message,true)}};
</script></body></html>